140	/**
141	 * Recursively auto-close done children when a parent is closed.
142	 * Appends system-authored events to each child's issue file and updates the index.
143	 * Returns the updated index.
144	 */
145	async function cascadeClose(
146	  index: IndexFile,
147	  issueId: IssueId,
148	  trackerDir: string,
149	): Promise<IndexFile> {
150	  const childIds = getChildren(index, issueId);
151	  let currentIndex = index;
152	
153	  for (const childId of childIds) {
154	    const childEntry = findEntry(currentIndex, childId);
155	    if (!childEntry || childEntry.status !== "done") continue;
156	
157	    const now = new Date().toISOString();
158	    const event: Event = {
159	      type: "update",
160	      timestamp: now,
161	      author: "system",
162	      content: {
163	        status: "closed",
164	        reason: "auto-closed: parent closed",
165	      },
166	    };
167	
168	    const childPath = join(trackerDir, childEntry.path);
169	    await appendEvent(childPath, event);
170	
171	    currentIndex = updateEntry(currentIndex, childId, { status: "closed" });
172	
173	    // Recursively cascade to the child's own children
174	    currentIndex = await cascadeClose(currentIndex, childId, trackerDir);
175	  }
176	
177	  return currentIndex;
178	}
