180	/**
181	 * Tracker — the main programmatic API for agentrack.
182	 *
183	 * Provides methods for issue CRUD, comments, blockages, user management,
184	 * and event history. The constructor accepts a `cwd` parameter that defaults
185	 * to `process.cwd()`. It does NOT validate that `.agentrack/` exists at
186	 * construction time — resolution happens on each method call.
187	 *
188	 * @example
189	 * ```typescript
190	 * import { Tracker } from "agentrack";
191	 *
192	 * const tracker = new Tracker("/path/to/project");
193	 * await tracker.init();
194	 * const { id } = await tracker.create({ title: "My first issue" });
195	 * ```
196	 */
197	export class Tracker {
198	  private cwd: string;
199	
200	  /**
201	   * Create a new Tracker instance.
202	   *
203	   * @param cwd - Working directory to resolve `.agentrack/` from. Defaults to `process.cwd()`.
204	   */
205	  constructor(cwd?: string) {
206	    this.cwd = cwd ?? process.cwd();
207	  }
208	
209	  /**
210	   * Initialize a new agentrack data directory in `cwd`.
211	   *
212	   * Creates the directory structure with all initial files:
213	   * `config.json`, `index.json`, `dependencies.json`, `users.json`,
214	   * and an empty `issues/` subdirectory.
215	   *
216	   * When `dirName` is not provided, resolves the directory from the pointer
217	   * file (`.agentrack.json`) or falls back to `.agentrack/`.
218	   *
219	   * @param dirName - Optional directory name override (e.g. ".testing")
220	   * @returns `{ result: "OK", path }` on success, or `{ result: "ALREADY_INITIALIZED", path }` if already exists
221	   *
222	   * @example
223	   * ```typescript
224	   * const result = await tracker.init();
225	   * if (result.result === "OK") console.log("Created at", result.path);
226	   * ```
227	   */
228	  async init(dirName?: string): Promise<InitResult> {
229	    const dir = dirName ?? resolveWorktreeOptions(this.cwd).dir;
230	    const trackerDir = join(this.cwd, dir);
231	
232	    if (existsSync(trackerDir)) {
233	      return { result: "ALREADY_INITIALIZED", path: resolve(trackerDir) };
234	    }
235	
236	    mkdirSync(trackerDir, { recursive: true });
237	    mkdirSync(join(trackerDir, "issues"), { recursive: true });
238	
239	    await atomicWriteJSON(join(trackerDir, "config.json"), DEFAULT_CONFIG);
240	    await atomicWriteJSON(join(trackerDir, "index.json"), DEFAULT_INDEX);
241	    await atomicWriteJSON(join(trackerDir, "dependencies.json"), DEFAULT_DEPENDENCIES);
242	    await atomicWriteJSON(join(trackerDir, "users.json"), DEFAULT_USERS);
243	    await atomicWriteJSON(join(trackerDir, "mentions.json"), {});
244	
245	    return { result: "OK", path: resolve(trackerDir) };
246	  }
