251	   * Generates a unique ID, creates the issue file with creation + update events,
252	   * and inserts an entry into the sorted index. Validates parent constraints if
253	   * `parentId` is provided.
254	   *
255	   * @param params - Creation parameters
256	   * @param params.title - The issue title (required)
257	   * @param params.description - Optional description, defaults to ""
258	   * @param params.status - Initial status, defaults to "idea"
259	   * @param params.priority - Priority 1-5, defaults to 3
260	   * @param params.assignee - Optional assignee, defaults to null
261	   * @param params.tags - Optional tags, defaults to []
262	   * @param params.parentId - Optional parent issue ID for hierarchy
263	   * @param params.author - Override author (resolved by auth layer if not provided)
264	   * @returns `{ id }` on success, or a AgentrackError on auth failure
265	   * @throws {AgentrackError} NOT_INITIALIZED if no `.agentrack/` directory
266	   * @throws {AgentrackError} NOT_FOUND if parentId doesn't exist in index
267	   * @throws {AgentrackError} HIERARCHY_CONSTRAINT if parent is closed
268	   *
269	   * @example
270	   * ```typescript
271	   * const { id } = await tracker.create({
272	   *   title: "Bug fix",
273	   *   priority: 1,
274	   *   tags: ["bug", "urgent"],
275	   * });
276	   * ```
277	   */
278	  async create(params: CreateParams): Promise<CreateResult> {
279	    const trackerDir = resolveTrackerDir(this.cwd);
280	    if (!trackerDir) {
281	      throw new AgentrackError(
282	        ErrorCodes.NOT_INITIALIZED.result,
283	        "No .agentrack/ directory found. Run `agt init` first.",
284	        ErrorCodes.NOT_INITIALIZED.exitCode,
285	      );
286	    }
287	
288	    const config = await readJSON<ConfigFile>(join(trackerDir, "config.json"));
289	    const users = await readJSON<UsersFile>(join(trackerDir, "users.json"));
290	    const authResult = resolveAuthor({ config, users, requiresWrite: true });
291	    if (authResult instanceof AgentrackError) return authResult;
292	    const author = params.author ?? authResult.author;
293	
294	    const id = generateId();
295	    const issuePath = params.path ?? `issues/${id}.json`;
296	    const now = new Date().toISOString();
297	
298	    const title = params.title;
299	    const description = params.description ?? "";
300	    const status: IssueStatus = params.status ?? "idea";
301	    const priority = params.priority ?? 3;
302	    const assignee = params.assignee ?? null;
303	    const parentId = params.parentId ?? null;
304	    const tags = params.tags ?? [];
305	
306	    // Read index early for parent validation
307	    const index = await readIndex(trackerDir);
308	
309	    // Validate parent exists and is not closed
310	    if (parentId) {
311	      const parentEntry = findEntry(index, parentId);
312	      if (!parentEntry) {
313	        throw new AgentrackError(
314	          ErrorCodes.NOT_FOUND.result,
315	          `Parent issue \`${parentId}\` not found in index.`,
316	          ErrorCodes.NOT_FOUND.exitCode,
317	        );
318	      }
319	      const validationError = validateNewChild(parentEntry);
320	      if (validationError) {
321	        throw new AgentrackError(
322	          ErrorCodes.HIERARCHY_CONSTRAINT.result,
323	          validationError,
324	          ErrorCodes.HIERARCHY_CONSTRAINT.exitCode,
325	        );
326	      }
327	    }
328	
329	    // Build update content with only non-default values
330	    const updateContent: Partial<
331	      Pick<
332	        IssueProperties,
333	        "title" | "description" | "status" | "assignee" | "tags" | "priority" | "parentId"
334	      >
335	    > & { title: string } = { title };
336	    if (description) updateContent.description = description;
337	    if (status !== "idea") updateContent.status = status;
338	    if (priority !== 3) updateContent.priority = priority;
339	    if (assignee !== null) updateContent.assignee = assignee;
340	    if (parentId !== null) updateContent.parentId = parentId;
341	    if (tags.length > 0) updateContent.tags = tags;
342	
343	    // Create issue file with two events: creation + update
344	    const creationEvent = { type: "creation" as const, timestamp: now, author };
345	    const updateEvent = {
346	      type: "update" as const,
347	      timestamp: now,
348	      author,
349	      content: updateContent,
350	    };
351	
352	    const issueFilePath = join(trackerDir, issuePath);
353	    await atomicWriteJSON(issueFilePath, [creationEvent, updateEvent]);
354	
355	    // Build index entry and insert into index
356	    const entry: IndexEntry = {
357	      id,
358	      title,
359	      path: issuePath,
360	      status,
361	      assignee,
362	      parentId,
363	      tags,
364	      priority,
365	    };
366	
367	    const updatedIndex = insertEntry(index, entry);
368	    await writeIndex(trackerDir, updatedIndex);
369	
370	    return { id };
