373	  /**
374	   * List issues from the index with optional filters.
375	   *
376	   * Returns entries sorted by: priority ASC → impact score DESC → id ASC.
377	   * Impact score is the count of active issues this issue blocks.
378	   *
379	   * @param params - Optional filter parameters
380	   * @param params.status - Filter by status; "open" = all non-closed, "closed" = closed only
381	   * @param params.assignee - Filter by assignee name
382	   * @param params.tags - AND filter — issue must have ALL specified tags
383	   * @param params.parentId - Filter by parent ID; null = top-level issues only
384	   * @returns Array of index entries matching the filters
385	   * @throws {AgentrackError} NOT_INITIALIZED if no `.agentrack/` directory
386	   * @throws {AgentrackError} TOKEN_REQUIRED if auth mode is strict and no token provided
387	   *
388	   * @example
389	   * ```typescript
390	   * const openUrgent = await tracker.list({
391	   *   status: "open",
392	   *   tags: ["urgent"],
393	   *   parentId: null,
394	   * });
395	   * ```
396	   */
397	  async list(params?: ListParams): Promise<ListResult> {
398	    const trackerDir = resolveTrackerDir(this.cwd);
399	    if (!trackerDir) {
400	      throw new AgentrackError(
401	        ErrorCodes.NOT_INITIALIZED.result,
402	        "No .agentrack/ directory found. Run `agt init` first.",
403	        ErrorCodes.NOT_INITIALIZED.exitCode,
404	      );
405	    }
406	
407	    const config = await readJSON<ConfigFile>(join(trackerDir, "config.json"));
408	    const users = await readJSON<UsersFile>(join(trackerDir, "users.json"));
409	    const authResult = resolveAuthor({ config, users, requiresWrite: false });
410	    if (authResult instanceof AgentrackError) {
411	      throw authResult;
412	    }
413	
414	    const index = await readIndex(trackerDir);
415	
416	    // Determine source arrays based on params.status
417	    let entries: IndexEntry[];
418	    if (params?.status === "closed") {
419	      entries = index.closed;
420	    } else if (params?.status === "open") {
421	      entries = index.open;
422	    } else if (params?.status) {
423	      entries = index.open;
424	    } else {
425	      entries = [...index.open, ...index.closed];
426	    }
427	
428	    // Filter in memory
429	    let filtered = entries;
430	
431	    if (params?.status && params.status !== "open" && params.status !== "closed") {
432	      filtered = filtered.filter((e) => e.status === params.status);
433	    }
434	
435	    if (params?.assignee) {
436	      filtered = filtered.filter((e) => e.assignee === params.assignee);
437	    }
438	
439	    if (params?.tags && params.tags.length > 0) {
440	      filtered = filtered.filter((e) => params.tags?.every((tag) => e.tags.includes(tag)));
441	    }
442	
443	    if (params?.parentId !== undefined) {
444	      if (params.parentId === null) {
445	        filtered = filtered.filter((e) => e.parentId === null);
446	      } else {
447	        filtered = filtered.filter((e) => e.parentId === params.parentId);
448	      }
449	    }
450	
451	    // Read dependencies once for impact score
452	    let deps: DependenciesFile | null = null;
453	
454	    // Sort: priority ASC → impact DESC → id ASC
455	    filtered.sort((a, b) => {
456	      if (a.priority !== b.priority) return a.priority - b.priority;
457	      // Lazy-load deps only once for sorting
458	      if (!deps) {
459	        deps = readDependenciesSync(trackerDir);
460	      }
461	      const impactA = getImpactScore(deps, a.id);
462	      const impactB = getImpactScore(deps, b.id);
463	      if (impactA !== impactB) return impactB - impactA;
464	      return a.id.localeCompare(b.id);
465	    });
466	
467	    return filtered;
468	  }
