528	  /**
529	   * Get the recommended next issue to work on for a given user.
530	   *
531	   * Filters open issues by assignee and active status, excludes blocked issues,
532	   * then sorts by priority ASC → impact DESC → id ASC and returns the top issue.
533	   *
534	   * @param assignee - The assignee name to filter by (case-sensitive)
535	   * @returns The recommended ComputedIssue, or `{ result: "NO_ISSUES_AVAILABLE" }`
536	   * @throws {AgentrackError} NOT_INITIALIZED if no `.agentrack/` directory
537	   * @throws {AgentrackError} TOKEN_REQUIRED if auth mode is strict and no token provided
538	   *
539	   * @example
540	   * ```typescript
541	   * const result = await tracker.next("alice");
542	   * if ("title" in result) console.log("Work on:", result.title);
543	   * else console.log("No issues available:", result.message);
544	   * ```
545	   */
546	  async next(assignee: string): Promise<NextResult> {
547	    const trackerDir = resolveTrackerDir(this.cwd);
548	    if (!trackerDir) {
549	      throw new AgentrackError(
550	        ErrorCodes.NOT_INITIALIZED.result,
551	        "No .agentrack/ directory found. Run `agt init` first.",
552	        ErrorCodes.NOT_INITIALIZED.exitCode,
553	      );
554	    }
555	
556	    const config = await readJSON<ConfigFile>(join(trackerDir, "config.json"));
557	    const users = await readJSON<UsersFile>(join(trackerDir, "users.json"));
558	    const authResult = resolveAuthor({ config, users, requiresWrite: false });
559	    if (authResult instanceof AgentrackError) {
560	      throw authResult;
561	    }
562	
563	    const index = await readIndex(trackerDir);
564	
565	    // Filter to open issues assigned to this user that are todo (ready to start)
566	    let candidates = index.open.filter(
567	      (e) => e.assignee === assignee && e.status === "todo",
568	    );
569	
570	    // Read dependencies for blockage filtering and impact scoring
571	    const deps = readDependenciesSync(trackerDir);
572	
573	    // Filter out issues with any active blockages
574	    candidates = candidates.filter((e) => {
575	      const blockedBy = deps.blockedBy[e.id] ?? [];
576	      return !blockedBy.some((b) => b.status === "active");
577	    });
578	
579	    // If no candidates remain, return no issues available
580	    if (candidates.length === 0) {
581	      return {
582	        result: "NO_ISSUES_AVAILABLE",
583	        message: `No todo issues found for user '${assignee}'.`,
584	      };
585	    }
586	
587	    // Sort: priority ASC → impact DESC → id ASC
588	    candidates.sort((a, b) => {
589	      if (a.priority !== b.priority) return a.priority - b.priority;
590	      const impactA = getImpactScore(deps, a.id);
591	      const impactB = getImpactScore(deps, b.id);
592	      if (impactA !== impactB) return impactB - impactA;
593	      return a.id.localeCompare(b.id);
594	    });
595	
596	    // Take top issue, replay events, return computed state
597	    const topEntry = candidates[0]!;
598	    const issueFilePath = join(trackerDir, topEntry.path);
599	    if (!existsSync(issueFilePath)) {
600	      throw new AgentrackError(
601	        ErrorCodes.ISSUE_MISSING.result,
602	        `Issue file for \`${topEntry.id}\` is missing.`,
603	        ErrorCodes.ISSUE_MISSING.exitCode,
604	      );
605	    }
606	
607	    const events = await replayEvents(issueFilePath);
608	    return computeState(events, topEntry.id);
609	  }
