639	   * ```
640	   */
641	  async update(id: IssueId, params: UpdateParams): Promise<UpdateResult> {
642	    const trackerDir = resolveTrackerDir(this.cwd);
643	    if (!trackerDir) {
644	      throw new AgentrackError(
645	        ErrorCodes.NOT_INITIALIZED.result,
646	        "No .agentrack/ directory found. Run `agt init` first.",
647	        ErrorCodes.NOT_INITIALIZED.exitCode,
648	      );
649	    }
650	
651	    // Validate at least one field provided (besides author)
652	    const hasField =
653	      params.title !== undefined ||
654	      params.description !== undefined ||
655	      params.status !== undefined ||
656	      params.assignee !== undefined ||
657	      params.tags !== undefined ||
658	      params.priority !== undefined ||
659	      params.parentId !== undefined;
660	
661	    if (!hasField) {
662	      throw new AgentrackError(
663	        ErrorCodes.INVALID_PARAMS.result,
664	        "At least one field must be provided for update.",
665	        ErrorCodes.INVALID_PARAMS.exitCode,
666	      );
667	    }
668	
669	    const config = await readJSON<ConfigFile>(join(trackerDir, "config.json"));
670	    const users = await readJSON<UsersFile>(join(trackerDir, "users.json"));
671	    const authResult = resolveAuthor({ config, users, requiresWrite: true });
672	    if (authResult instanceof AgentrackError) return authResult;
673	    const author = params.author ?? authResult.author;
674	
675	    const index = await readIndex(trackerDir);
676	    const entry = findEntry(index, id);
677	    if (!entry) {
678	      throw new AgentrackError(
679	        ErrorCodes.NOT_FOUND.result,
680	        `Issue \`${id}\` not found in index.`,
681	        ErrorCodes.NOT_FOUND.exitCode,
682	      );
683	    }
684	
685	    const issueFilePath = join(trackerDir, entry.path);
686	    if (!existsSync(issueFilePath)) {
687	      throw new AgentrackError(
688	        ErrorCodes.ISSUE_MISSING.result,
689	        `Issue file for \`${id}\` is missing.`,
690	        ErrorCodes.ISSUE_MISSING.exitCode,
691	      );
692	    }
693	
694	    // Save old values for hierarchy handling
695	    const oldStatus = entry.status;
696	    const oldParentId = entry.parentId;
697	
698	    // ── Hierarchy validation (before any state changes) ────────────
699	
700	    // Validate downward constraints for status change
701	    if (params.status !== undefined && params.status !== oldStatus) {
702	      if (params.status === "done" || params.status === "closed") {
703	        const childIds = getChildren(index, id);
704	        const childEntries = childIds
705	          .map((cid) => findEntry(index, cid))
706	          .filter((e): e is IndexEntry => e !== null);
707	        const validationError = validateParentStatusChange(index, childEntries, params.status);
708	        if (validationError) {
709	          throw new AgentrackError(
710	            ErrorCodes.HIERARCHY_CONSTRAINT.result,
711	            validationError,
712	            ErrorCodes.HIERARCHY_CONSTRAINT.exitCode,
713	          );
714	        }
715	      }
716	    }
717	
718	    // Validate reparenting constraints
719	    if (params.parentId !== undefined && params.parentId !== oldParentId) {
720	      if (params.parentId !== null) {
721	        const newParentEntry = findEntry(index, params.parentId);
722	        if (!newParentEntry) {
723	          throw new AgentrackError(
724	            ErrorCodes.NOT_FOUND.result,
725	            `Parent issue \`${params.parentId}\` not found in index.`,
726	            ErrorCodes.NOT_FOUND.exitCode,
727	          );
728	        }
729	        const validationError = validateNewChild(newParentEntry);
730	        if (validationError) {
731	          throw new AgentrackError(
732	            ErrorCodes.HIERARCHY_CONSTRAINT.result,
733	            validationError,
734	            ErrorCodes.HIERARCHY_CONSTRAINT.exitCode,
735	          );
736	        }
737	      }
738	    }
739	
740	    // ── Build and append update event ──────────────────────────────
741	
742	    // Build update event content with only the provided fields
743	    const content: Partial<
744	      Pick<
745	        IssueProperties,
746	        "title" | "description" | "status" | "assignee" | "tags" | "priority" | "parentId"
747	      >
748	    > = {};
749	    if (params.title !== undefined) content.title = params.title;
750	    if (params.description !== undefined) content.description = params.description;
751	    if (params.status !== undefined) content.status = params.status;
752	    if (params.assignee !== undefined) content.assignee = params.assignee;
753	    if (params.tags !== undefined) content.tags = params.tags;
754	    if (params.priority !== undefined) content.priority = params.priority;
755	    if (params.parentId !== undefined) content.parentId = params.parentId;
756	
757	    const now = new Date().toISOString();
758	
759	    const updateEvent = {
760	      type: "update" as const,
761	      timestamp: now,
762	      author,
763	      content,
764	    };
765	
766	    // Append event to issue file
767	    await appendEvent(issueFilePath, updateEvent);
768	
769	    // Recompute state from all events
770	    const events = await replayEvents(issueFilePath);
771	    const computed = computeState(events, id);
772	
773	    // Update index entry with new computed values
774	    let updatedIndex = updateEntry(index, id, {
775	      title: computed.title,
776	      status: computed.status,
777	      assignee: computed.assignee,
778	      parentId: computed.parentId,
779	      tags: computed.tags,
780	      priority: computed.priority,
781	    });
782	
783	    // ── Hierarchy handling (after event append, before index write) ─
784	
785	    // 1. Handle reparenting (childrenOf updates)
786	    if (params.parentId !== undefined && params.parentId !== oldParentId) {
787	      // Detach from old parent
788	      if (oldParentId !== null) {
789	        updatedIndex = removeChild(updatedIndex, oldParentId, id);
790	      }
791	      // Attach to new parent
792	      if (params.parentId !== null) {
793	        updatedIndex = addChild(updatedIndex, params.parentId, id);
794	
795	        // Upward promotion for reparenting: if child's status is past new parent's status
796	        const newParentEntry = findEntry(updatedIndex, params.parentId);
797	        if (newParentEntry && isStatusAfter(computed.status, newParentEntry.status)) {
798	          const promotions = computeUpwardPromotions(
799	            updatedIndex,
800	            newParentEntry,
801	            computed.status,
802	            (iid) => findEntry(updatedIndex, iid),
803	          );
804	          for (const promo of promotions) {
805	            const promoEntry = findEntry(updatedIndex, promo.issueId);
806	            if (promoEntry && promo.event.type === "update" && promo.event.content.status) {
807	              await appendEvent(join(trackerDir, promoEntry.path), promo.event);
808	              updatedIndex = updateEntry(updatedIndex, promo.issueId, {
809	                status: promo.event.content.status,
810	              });
811	            }
812	          }
813	        }
814	      }
815	    }
816	
817	    // 2. Handle status change
818	    if (params.status !== undefined && params.status !== oldStatus) {
