822	      }
823	
824	      // Upward promotion: promote parent if child advanced past it
825	      const currentParentId = computed.parentId;
826	      if (currentParentId) {
827	        const parentEntry = findEntry(updatedIndex, currentParentId);
828	        if (parentEntry && isStatusAfter(params.status, parentEntry.status)) {
829	          const promotions = computeUpwardPromotions(
830	            updatedIndex,
831	            parentEntry,
832	            params.status,
833	            (iid) => findEntry(updatedIndex, iid),
834	          );
835	          for (const promo of promotions) {
836	            const promoEntry = findEntry(updatedIndex, promo.issueId);
837	            if (promoEntry && promo.event.type === "update" && promo.event.content.status) {
838	              await appendEvent(join(trackerDir, promoEntry.path), promo.event);
839	              updatedIndex = updateEntry(updatedIndex, promo.issueId, {
840	                status: promo.event.content.status,
841	              });
842	            }
843	          }
844	        }
845	      }
846	    }
847	
848	    await writeIndex(trackerDir, updatedIndex);
849	
850	    // ── Auto-resolution: resolve active blockages when issue → done/closed ──
851	    if (params.status !== undefined && params.status !== oldStatus) {
852	      if (params.status === "done" || params.status === "closed") {
853	        const deps = await readDependencies(trackerDir);
854	        const activeBlocks = (deps.blocks[id] ?? []).filter((e) => e.status === "active");
855	
856	        if (activeBlocks.length > 0) {
857	          let updatedDeps = deps;
858	          for (const entry of activeBlocks) {
859	            updatedDeps = resolveBlockage(updatedDeps, entry.blockedId, entry.blockerId);
860	
861	            const blockedEntry = findEntry(updatedIndex, entry.blockedId);
862	            if (blockedEntry) {
863	              const now = new Date().toISOString();
864	              const resolveEvent: Event = {
865	                type: "blockage-resolved",
866	                timestamp: now,
867	                author: "system",
868	                content: {
