1278	   * is rejected and no changes are written. Validates that both the blocked issue
1279	   * and all blocker issues exist in the index.
1280	   *
1281	   * @param blockedId - The issue that is blocked
1282	   * @param params - Blockage parameters
1283	   * @param params.blockerIds - Array of blocker issue IDs
1284	   * @param params.author - Override author (resolved by auth layer if not provided)
1285	   * @returns `{ result: "OK" }` on success, or a AgentrackError
1286	   * @throws {AgentrackError} NOT_INITIALIZED if no `.agentrack/` directory
1287	   * @throws {AgentrackError} NOT_FOUND if blockedId or any blockerId is not in the index
1288	   * @throws {AgentrackError} BLOCKAGE_CYCLE if adding the blockage would create a cycle
1289	   *
1290	   * @example
1291	   * ```typescript
1292	   * await tracker.blockagesAdd("blocked001", {
1293	   *   blockerIds: ["blocker001", "blocker002"],
1294	   * });
1295	   * ```
1296	   */
1297	  async blockagesAdd(blockedId: IssueId, params: BlockagesAddParams): Promise<BlockagesAddResult> {
1298	    const trackerDir = resolveTrackerDir(this.cwd);
1299	    if (!trackerDir) {
1300	      throw new AgentrackError(
1301	        ErrorCodes.NOT_INITIALIZED.result,
1302	        "No .agentrack/ directory found. Run `agt init` first.",
1303	        ErrorCodes.NOT_INITIALIZED.exitCode,
1304	      );
1305	    }
1306	
1307	    const config = await readJSON<ConfigFile>(join(trackerDir, "config.json"));
1308	    const users = await readJSON<UsersFile>(join(trackerDir, "users.json"));
1309	    const authResult = resolveAuthor({ config, users, requiresWrite: true });
1310	    if (authResult instanceof AgentrackError) return authResult;
1311	    const author = params.author ?? authResult.author;
1312	
1313	    const index = await readIndex(trackerDir);
1314	
1315	    // Validate blockedId exists
1316	    if (!findEntry(index, blockedId)) {
1317	      throw new AgentrackError(
1318	        ErrorCodes.NOT_FOUND.result,
1319	        `Issue \`${blockedId}\` not found in index.`,
1320	        ErrorCodes.NOT_FOUND.exitCode,
1321	      );
1322	    }
1323	
1324	    // Validate all blockerIds exist
1325	    for (const blockerId of params.blockerIds) {
1326	      if (!findEntry(index, blockerId)) {
1327	        throw new AgentrackError(
1328	          ErrorCodes.NOT_FOUND.result,
1329	          `Issue \`${blockerId}\` not found in index.`,
1330	          ErrorCodes.NOT_FOUND.exitCode,
1331	        );
1332	      }
1333	    }
1334	
1335	    const deps = await readDependencies(trackerDir);
1336	
1337	    // Projected state: deep clone and validate cycle for each blocker
1338	    let projected = {
1339	      blockedBy: { ...deps.blockedBy },
1340	      blocks: { ...deps.blocks },
1341	    };
1342	
1343	    for (const blockerId of params.blockerIds) {
1344	      projected = addBlockage(projected, blockedId, blockerId);
1345	      if (detectCycle(projected, blockedId, blockerId)) {
1346	        throw new AgentrackError(
1347	          ErrorCodes.BLOCKAGE_CYCLE.result,
1348	          `Blockage would create a cycle: \`${blockedId}\` → ... → \`${blockerId}\`.`,
1349	          ErrorCodes.BLOCKAGE_CYCLE.exitCode,
1350	        );
1351	      }
1352	    }
1353	
1354	    // All passed — write projected state
1355	    await writeDependencies(trackerDir, projected);
1356	
1357	    // Append events to blockedId's issue file
1358	    const blockedEntry = findEntry(index, blockedId)!;
1359	    const issueFilePath = join(trackerDir, blockedEntry.path);
1360	
1361	    for (const blockerId of params.blockerIds) {
1362	      const now = new Date().toISOString();
1363	      const event: Event = {
1364	        type: "blockage-added",
1365	        timestamp: now,
1366	        author,
1367	        content: { blockerId },
1368	      };
1369	      await appendEvent(issueFilePath, event);
1370	    }
1371	
1372	    return { result: "OK" };
1373	  }
